static const char str204[] = "Uya 编译器 - 零GC系统编程语言\n";
static const char str205[] = "版本：v0.9.4\n";
static const char str206[] = "\n用法:\n";
static const char str207[] = "  %s build <文件> [-o <输出>] [选项]  编译为可执行文件或中间产物\n";
static const char str208[] = "  %s build --app microapp <文件> -o <xxx.pobj|xxx.uapp>  输出 microapp 载荷对象或镜像\n";
static const char str209[] = "  %s pack-image <xxx.pobj> -o <xxx.uapp>  将 microapp 载荷对象打包为 .uapp\n";
static const char str210[] = "  %s inspect-image <xxx.pobj|xxx.uapp>  打印 microapp 头信息\n";
static const char str211[] = "  %s verify-image <xxx.pobj|xxx.uapp>   校验 microapp 镜像或载荷对象\n";
static const char str212[] = "  %s run <文件> [选项] [-- <参数>...]  编译并运行\n";
static const char str213[] = "  %s test <文件> [选项]               编译测试并运行（子进程栈：--stack-size 或默认 65536 KB）\n";
static const char str214[] = "  %s --outlibc <目录>                 生成独立 libc\n";
static const char str215[] = "\n示例:\n";
static const char str216[] = "  %s build main.uya -o myapp\n";
static const char str217[] = "  %s pack-image hello.pobj -o hello.uapp\n";
static const char str218[] = "  %s inspect-image hello.uapp\n";
static const char str219[] = "  %s verify-image hello.uapp\n";
static const char str220[] = "  %s run main.uya\n";
static const char str221[] = "  %s test tests.uya\n";
static const char str222[] = "  %s build main.uya -o main.c --c99   # 生成 C99 代码\n";
static const char str223[] = "  %s build --app microapp main.uya -o microapp.uapp  # 微应用模式\n";
static const char str224[] = "  MICROAPP_TARGET_PROFILE=linux_x86_64_hardvm %s build --app microapp main.uya -o microapp.uapp\n";
static const char str225[] = "  TARGET_OS=macos TARGET_ARCH=arm64 %s build --app microapp main.uya -o microapp.uapp  # 按目标平台自动推导 profile\n";
static const char str226[] = "\n选项:\n";
static const char str227[] = "  --c99                使用 C99 后端生成 C 代码\n";
static const char str228[] = "  --app <app|microapp>  选择应用类型；app 为默认行为，microapp 会启用更严格检查\n";
static const char str229[] = "  --microapp-profile <name>  覆盖 microapp target profile（推荐优先使用；优先于 MICROAPP_TARGET_PROFILE）\n";
static const char str230[] = "  --line-directives    启用 #line 指令生成（C99 后端）\n";
static const char str231[] = "  --no-line-directives 禁用 #line 指令生成\n";
static const char str232[] = "  --opt=<0-3>          优化级别（0=禁用, 1=默认, 2=+证明优化, 3=+内联）\n";
static const char str233[] = "  -O0, -O1, -O2, -O3   优化级别（简写形式）\n";
static const char str234[] = "  --safety-proof       启用内存安全证明（默认已启用）\n";
static const char str235[] = "  --no-safety-proof    禁用内存安全证明\n";
static const char str236[] = "  --nostdlib           完全独立模式：无标准库依赖，使用 syscall\n";
static const char str237[] = "  --async-frame-heap=on  async frame pool 满时回退到调试 heap（默认关闭）\n";
static const char str238[] = "  MICROAPP_TARGET_CFLAGS  microapp 目标 gcc 编译旗标；call_gate profile 默认 -std=c99 -Os -fomit-frame-pointer -fno-builtin -fno-stack-protector -fpie -ffunction-sections -fdata-sections -flto=auto，trap profile 默认改为 -fno-pie（均不含 -g）\n";
static const char str239[] = "  MICROAPP_TARGET_LDFLAGS microapp 目标 gcc 链接旗标；call_gate profile 默认 -pie -Wl,--gc-sections -flto=auto，trap profile 默认改为 -no-pie\n";
static const char str240[] = "  -o <文件>            指定输出文件名\n";
static const char str241[] = "  --stack-size <KB>    设置堆栈大小（KB），默认 65536 (64MB)\n";
static const char str242[] = "  --split-c-dir [<dir>]  多文件 C 输出；省略或 --split-c-dir= 时目录默认为 .uyacache\n";
static const char str243[] = "  --split-c-dir=<dir>  同上（合并写法；空路径等价于默认 .uyacache）\n";
static const char str244[] = "  --no-split-c         关闭多文件 C（单文件/临时 .c；忽略 UYA_SPLIT_C_DIR 与 --split-c-dir）\n";
static const char str245[] = "  C99 默认多文件输出到 .uyacache（显式 -o xxx.c 或 UYA_SPLIT_C=0|false|no|off 时为单文件）\n";
static const char str246[] = "  多文件布局：默认镜像分 TU（一源一 .c，便于 make -j）；UYA_SPLIT_C_MIRROR=0|false|no|off 时用 uya_part1+part2\n";
static const char str247[] = "  -h, --help           显示此帮助信息\n";
static const char str248[] = "  -v, --version        显示版本信息\n";
static const char str249[] = "\n微应用环境变量:\n";
static const char str250[] = "  MICROAPP_TARGET_PROFILE microapp 目标 profile；推荐优先使用；可选 linux_x86_64_hardvm / linux_aarch64_hardvm / macos_arm64_hardvm / rv32_baremetal_softvm / xtensa_baremetal_softvm\n";
static const char str251[] = "  MICROAPP_TARGET_ARCH    microapp 目标架构；仅在未显式指定 profile 时参与回退推导\n";
static const char str252[] = "  TARGET_OS/TARGET_ARCH  未显式指定 profile 时，优先按目标平台组合推导默认 profile\n";
