static const char str595[] = "static inline int64_t uya_syscall0(int64_t n) {\n";
static const char str596[] = "    long ret;\n";
static const char str597[] = "    __asm__ volatile(\"syscall\" : \"=a\"(ret) : \"a\"(n) : \"rcx\", \"r11\", \"cc\", \"memory\");\n";
