static const char str599[] = "}\n";
static const char str600[] = "static inline int64_t uya_syscall1(int64_t n, int64_t a1) {\n";
static const char str601[] = "    __asm__ volatile(\"syscall\" : \"=a\"(ret) : \"a\"(n), \"D\"(a1) : \"rcx\", \"r11\", \"cc\", \"memory\");\n";
static const char str602[] = "static inline int64_t uya_syscall2(int64_t n, int64_t a1, int64_t a2) {\n";
static const char str603[] = "    __asm__ volatile(\"syscall\" : \"=a\"(ret) : \"a\"(n), \"D\"(a1), \"S\"(a2) : \"rcx\", \"r11\", \"cc\", \"memory\");\n";
static const char str604[] = "static inline int64_t uya_syscall3(int64_t n, int64_t a1, int64_t a2, int64_t a3) {\n";
static const char str605[] = "    __asm__ volatile(\"syscall\" : \"=a\"(ret) : \"a\"(n), \"D\"(a1), \"S\"(a2), \"d\"(a3) : \"rcx\", \"r11\", \"cc\", \"memory\");\n";
static const char str606[] = "/* std.thread / microapp：函数指针间接调用（与 codegen 前导一致；勿用 inline 以免 -O2 内联退化） */\n";
static const char str607[] = "static int32_t uya_call0_i32(void *fn) {\n";
static const char str608[] = "    typedef int32_t (*uya_fn0_i32)(void);\n";
static const char str609[] = "    return ((uya_fn0_i32)fn)();\n";
static const char str610[] = "static int32_t uya_call0_i32_stack(void *fn, void *stack_top) {\n";
static const char str611[] = "#if defined(__x86_64__) || defined(_M_X64)\n";
static const char str612[] = "    uintptr_t top = ((uintptr_t)stack_top) & ~(uintptr_t)0xFUL;\n";
static const char str613[] = "    int32_t ret;\n";
static const char str614[] = "    __asm__ volatile(\n";
static const char str615[] = "        \"mov %%rsp, %%rbx\\n\\t\"\n";
static const char str616[] = "        \"mov %1, %%rsp\\n\\t\"\n";
static const char str617[] = "        \"call *%2\\n\\t\"\n";
static const char str618[] = "        \"mov %%rbx, %%rsp\\n\\t\"\n";
static const char str619[] = "        : \"=a\"(ret)\n";
static const char str620[] = "        : \"r\"((void *)top), \"r\"(fn)\n";
static const char str621[] = "        : \"rbx\", \"rcx\", \"rdx\", \"rsi\", \"rdi\", \"r8\", \"r9\", \"r10\", \"r11\", \"memory\", \"cc\");\n";
static const char str622[] = "#elif defined(__aarch64__) || defined(_M_ARM64)\n";
static const char str623[] = "        \"mov x9, sp\\n\\t\"\n";
static const char str624[] = "        \"mov sp, %1\\n\\t\"\n";
static const char str625[] = "        \"blr %2\\n\\t\"\n";
static const char str626[] = "        \"mov %w0, w0\\n\\t\"\n";
static const char str627[] = "        \"mov sp, x9\\n\\t\"\n";
static const char str628[] = "        : \"=r\"(ret)\n";
static const char str629[] = "        : \"x0\", \"x9\", \"x30\", \"memory\", \"cc\");\n";
static const char str630[] = "#else\n";
static const char str631[] = "    (void)stack_top;\n";
static const char str632[] = "#endif\n";
static const char str633[] = "static int32_t uya_thread_call_i32(void *fn, int32_t arg) {\n";
