static __attribute__((used)) struct ASTNode * ast_merge_programs(struct ASTNode * programs_param[128], int32_t count, struct CompilerArena * arena) {
    // 数组参数按值传递：创建局部副本
    struct ASTNode * programs[128];
        __uya_memcpy(programs, programs_param, sizeof(programs));
    (void)programs_param;
    (void)count;
    (void)arena;
    if (((count <= 0) || (arena == NULL))) {
        struct ASTNode * _uya_ret = NULL;
        return _uya_ret;
    }
    int32_t i = 0;
    while (i < count) {
        struct ASTNode * const p = programs[i];
        if (((p == NULL) || (p->type != ASTNodeType_AST_PROGRAM))) {
            struct ASTNode * _uya_ret = NULL;
            return _uya_ret;
        }
        i = (i + 1);
    }
    int32_t total_decl_count = 0;
    i = 0;
    while (i < count) {
        total_decl_count = (total_decl_count + programs[i]->program_decl_count);
        i = (i + 1);
    }
    struct ASTNode * const first = programs[0];
    struct ASTNode * const merged = ast_new_node(ASTNodeType_AST_PROGRAM, first->line, first->column, arena, first->filename);
    if (merged == NULL) {
        struct ASTNode * _uya_ret = NULL;
        return _uya_ret;
    }
    if (total_decl_count <= 0) {
        merged->program_decls = NULL;
        merged->program_decl_count = 0;
        struct ASTNode * _uya_ret = merged;
        return _uya_ret;
    }
    struct ASTNode * * const decls = (struct ASTNode * *)compiler_arena_alloc(arena, ((int32_t)sizeof(struct ASTNode *) * (size_t)total_decl_count));
    if (decls == NULL) {
        struct ASTNode * _uya_ret = NULL;
        return _uya_ret;
    }
    int32_t decl_index = 0;
    i = 0;
    while (i < count) {
        struct ASTNode * const program = programs[i];
        int32_t j = 0;
        while (j < program->program_decl_count) {
            decls[decl_index] = program->program_decls[j];
            decl_index = (decl_index + 1);
            j = (j + 1);
        }
        i = (i + 1);
    }
    merged->program_decls = decls;
    merged->program_decl_count = total_decl_count;
    struct ASTNode * _uya_ret = merged;
    return _uya_ret;
}

