static __attribute__((used)) void collect_err_union_from_ast(struct C99CodeGenerator * codegen, struct ASTNode * node) {
    (void)codegen;
    (void)node;
    if (((codegen == NULL) || (node == NULL))) {
        return;
    }
    if (node->type == ASTNodeType_AST_TRY_EXPR) {
        if (((codegen->checker != NULL) && (node->try_expr_operand != NULL))) {
            int32_t registered = 0;
            struct ASTNode * const operand = node->try_expr_operand;
            if ((((operand->type == ASTNodeType_AST_MATCH_EXPR) && (operand->match_expr_arm_count > 0)) && (operand->match_expr_arms != NULL))) {
                struct ASTNode * first_result = NULL;
                int32_t ai = 0;
                while (ai < operand->match_expr_arm_count) {
                    struct ASTMatchArm arm = operand->match_expr_arms[ai];
                    if (((arm.result_expr != NULL) && (arm.result_expr->type != ASTNodeType_AST_ERROR_VALUE))) {
                        first_result = arm.result_expr;
                        ai = operand->match_expr_arm_count;
                    }
                    ai = (ai + 1);
                }
                if (first_result != NULL) {
                    struct ASTNode * payload_ast = NULL;
                    struct ASTNode * infer_node = first_result;
                    if ((((first_result->type == ASTNodeType_AST_BLOCK) && (first_result->block_stmts != NULL)) && (first_result->block_stmt_count > 0))) {
                        struct ASTNode * tail_expr = NULL;
                        ai = (first_result->block_stmt_count - 1);
                        while (ai >= 0) {
                            struct ASTNode * const st = first_result->block_stmts[ai];
                            if (((((((((((((st != NULL) && (st->type != ASTNodeType_AST_VAR_DECL)) && (st->type != ASTNodeType_AST_RETURN_STMT)) && (st->type != ASTNodeType_AST_IF_STMT)) && (st->type != ASTNodeType_AST_WHILE_STMT)) && (st->type != ASTNodeType_AST_FOR_STMT)) && (st->type != ASTNodeType_AST_BREAK_STMT)) && (st->type != ASTNodeType_AST_CONTINUE_STMT)) && (st->type != ASTNodeType_AST_DEFER_STMT)) && (st->type != ASTNodeType_AST_ERRDEFER_STMT)) && (st->type != ASTNodeType_AST_ASSIGN)) && (st->type != ASTNodeType_AST_EXPR_STMT))) {
                                tail_expr = st;
                                ai = (-1);
                            }
                            ai = (ai - 1);
                        }
                        if (tail_expr != NULL) {
                            infer_node = tail_expr;
                        }
                        if ((((tail_expr != NULL) && (tail_expr->type == ASTNodeType_AST_IDENTIFIER)) && (tail_expr->identifier_name != NULL))) {
                            ai = (first_result->block_stmt_count - 1);
                            while (ai >= 0) {
                                struct ASTNode * const st2 = first_result->block_stmts[ai];
                                if ((((((st2 != NULL) && (st2->type == ASTNodeType_AST_VAR_DECL)) && (st2->var_decl_name != NULL)) && (st2->var_decl_type != NULL)) && (std_string_strcmp((uint8_t *)st2->var_decl_name, (uint8_t *)tail_expr->identifier_name) == 0))) {
                                    payload_ast = st2->var_decl_type;
                                    ai = (-1);
                                }
                                ai = (ai - 1);
                            }
                        }
                    }
                    if (payload_ast != NULL) {
                        struct ASTNode * const eu_node = ast_new_node(ASTNodeType_AST_TYPE_ERROR_UNION, 0, 0, codegen->arena, NULL);
                        if (eu_node != NULL) {
                            eu_node->type_error_union_payload_type = payload_ast;
                            (void)(c99_type_to_c(codegen, eu_node)                            );
                            registered = 1;
                        }
                    }
                    if (((registered == 0) && (infer_node != NULL))) {
                        struct Type payload_type = checker_check_expr_checker_infer_type(codegen->checker, infer_node);
                        if (payload_type.kind == TypeKind_TYPE_ERROR_UNION) {
                            struct ASTNode * const try_ast = checker_type_from_ast_type_to_ast(codegen->checker, (&payload_type), node->line, node->column, node->filename);
                            if (try_ast != NULL) {
                                (void)(c99_type_to_c(codegen, try_ast)                                );
                                registered = 1;
                            }
                        } else {
                            if (payload_type.kind != TypeKind_TYPE_VOID) {
                                struct Type * const payload_ptr = (struct Type *)compiler_arena_alloc(codegen->checker->arena, (int32_t)sizeof(struct Type));
                                if (payload_ptr != NULL) {
                                    payload_ptr[0] = payload_type;
                                    struct Type eu_type = checker_type_utils_make_error_union_type(codegen->checker->arena, payload_ptr);
                                    struct ASTNode * const try_ast = checker_type_from_ast_type_to_ast(codegen->checker, (&eu_type), node->line, node->column, node->filename);
                                    if (try_ast != NULL) {
                                        (void)(c99_type_to_c(codegen, try_ast)                                        );
                                        registered = 1;
                                    }
                                }
                            }
                        }
                    }
                    if ((((((registered == 0) && (node->try_expr_operand != NULL)) && (node->try_expr_operand->type == ASTNodeType_AST_AWAIT_EXPR)) && (node->try_expr_operand->await_expr_operand != NULL)) && (codegen->current_function_decl != NULL))) {
                        struct ASTNode * const await_try_ast2 = c99_async_await_result_ast(codegen, node->try_expr_operand, codegen->current_function_decl);
                        if (await_try_ast2 != NULL) {
                            struct ASTNode * const eu_node2 = ast_new_node(ASTNodeType_AST_TYPE_ERROR_UNION, node->line, node->column, codegen->arena, node->filename);
                            if (eu_node2 != NULL) {
                                eu_node2->type_error_union_payload_type = await_try_ast2;
                                (void)(c99_type_to_c(codegen, eu_node2)                                );
                                registered = 1;
                            }
                        }
                    }
                }
            }
            if (registered == 0) {
                struct Type try_type = checker_check_expr_checker_infer_type(codegen->checker, node);
                if (try_type.kind == TypeKind_TYPE_ERROR_UNION) {
                    struct ASTNode * const try_ast = checker_type_from_ast_type_to_ast(codegen->checker, (&try_type), node->line, node->column, node->filename);
                    if (try_ast != NULL) {
                        (void)(c99_type_to_c(codegen, try_ast)                        );
                    }
                }
            }
        }
        (void)(collect_err_union_from_ast(codegen, node->try_expr_operand)        );
        return;
    }
    if (((node->type == ASTNodeType_AST_BLOCK) && (node->block_stmts != NULL))) {
        int32_t i = 0;
        while (i < node->block_stmt_count) {
            (void)(collect_err_union_from_ast(codegen, node->block_stmts[i])            );
            i = (i + 1);
        }
    } else {
        if (node->type == ASTNodeType_AST_IF_STMT) {
            if (node->if_stmt_condition != NULL) {
                (void)(collect_err_union_from_ast(codegen, node->if_stmt_condition)                );
            }
            if (node->if_stmt_then_branch != NULL) {
                (void)(collect_err_union_from_ast(codegen, node->if_stmt_then_branch)                );
            }
            if (node->if_stmt_else_branch != NULL) {
                (void)(collect_err_union_from_ast(codegen, node->if_stmt_else_branch)                );
            }
        } else {
            if (((node->type == ASTNodeType_AST_WHILE_STMT) && (node->while_stmt_body != NULL))) {
                (void)(collect_err_union_from_ast(codegen, node->while_stmt_body)                );
            } else {
                if (((node->type == ASTNodeType_AST_FOR_STMT) && (node->for_stmt_body != NULL))) {
                    (void)(collect_err_union_from_ast(codegen, node->for_stmt_body)                    );
                } else {
                    if (node->type == ASTNodeType_AST_VAR_DECL) {
                        if (node->var_decl_init != NULL) {
                            (void)(collect_err_union_from_ast(codegen, node->var_decl_init)                            );
                        }
                    } else {
                        if (((node->type == ASTNodeType_AST_RETURN_STMT) && (node->return_stmt_expr != NULL))) {
                            (void)(collect_err_union_from_ast(codegen, node->return_stmt_expr)                            );
                        } else {
                            if (((node->type == ASTNodeType_AST_ASSIGN) && (node->assign_src != NULL))) {
                                (void)(collect_err_union_from_ast(codegen, node->assign_src)                                );
                            } else {
                                if (node->type == ASTNodeType_AST_CALL_EXPR) {
                                    if (node->call_expr_args != NULL) {
                                        int32_t i = 0;
                                        while (i < node->call_expr_arg_count) {
                                            (void)(collect_err_union_from_ast(codegen, node->call_expr_args[i])                                            );
                                            i = (i + 1);
                                        }
                                    }
                                } else {
                                    if (node->type == ASTNodeType_AST_MATCH_EXPR) {
                                        if (node->match_expr_expr != NULL) {
                                            (void)(collect_err_union_from_ast(codegen, node->match_expr_expr)                                            );
                                        }
                                        if (node->match_expr_arms != NULL) {
                                            int32_t a = 0;
                                            while (a < node->match_expr_arm_count) {
                                                if (node->match_expr_arms[a].result_expr != NULL) {
                                                    (void)(collect_err_union_from_ast(codegen, node->match_expr_arms[a].result_expr)                                                    );
                                                }
                                                a = (a + 1);
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

