void codegen_c99_utils_c99_write_mirror_manifest(struct C99CodeGenerator * codegen, struct ASTNode * program) {
    (void)codegen;
    (void)program;
    if ((((codegen == NULL) || (codegen->split_enabled == 0)) || (codegen->split_dir == NULL))) {
        return;
    }
    if (((program == NULL) || (program->type != ASTNodeType_AST_PROGRAM))) {
        return;
    }
    uint8_t mp[1024] = {0};
    const int32_t mpl = snprintf((char *)(uint8_t *)(&mp[0]), 1024, (const char *)"%s/mirror_manifest.txt", (uint8_t *)codegen->split_dir);
    if (((mpl <= 0) || (mpl >= 1024))) {
        return;
    }
    void * const mf = std_io_fopen((uint8_t *)(&mp[0]), (uint8_t *)(uint8_t *)str358);
    if (mf == NULL) {
        return;
    }
    (void)(std_io_fputs((uint8_t *)(uint8_t *)"# 合并 AST 中出现的源文件路径（去重），一行一个；用于后续按目录镜像拆分为多 .c\n", (void *)mf)    );
    uint8_t uniq[128][512] = {0};
    int32_t uniq_count = 0;
    int32_t di = 0;
    while (di < program->program_decl_count) {
        struct ASTNode * const decl = program->program_decls[di];
        if (((decl != NULL) && (decl->filename != NULL))) {
            uint8_t * const fnm = decl->filename;
            int32_t found = 0;
            int32_t u = 0;
            while (u < uniq_count) {
                if (std_string_strcmp((uint8_t *)(&uniq[u][0]), (uint8_t *)fnm) == 0) {
                    found = 1;
                    u = uniq_count;
                }
                u = (u + 1);
            }
            if (((found == 0) && (uniq_count < 128))) {
                if (((uniq_count >= 0) && (uniq_count < 128))) {
                    int32_t z = 0;
                    while (((z < 511) && (fnm[z] != (uint8_t)0))) {
                        if (((z >= 0) && (z < sizeof(uniq[uniq_count]) / sizeof((uniq[uniq_count])[0])))) {
                            uniq[uniq_count][z] = fnm[z];
                        }
                        z = (z + 1);
                    }
                    if (((z >= 0) && (z < sizeof(uniq[uniq_count]) / sizeof((uniq[uniq_count])[0])))) {
                        uniq[uniq_count][z] = (uint8_t)0;
                    }
                }
                (void)(std_io_fputs((uint8_t *)(&uniq[uniq_count][0]), (void *)mf)                );
                (void)(std_io_fputc(10, (void *)mf)                );
                uniq_count = (uniq_count + 1);
            }
        }
        di = (di + 1);
    }
    (void)(std_io_fclose((void *)mf));
}

