    (void)(std_io_fputs((uint8_t *)(uint8_t *)"\n// 字符串常量（char 类型以满足 -Wformat= 对 fprintf/snprintf 格式参数的要求）\n", (void *)codegen->emit_stream)    );
    int32_t i = 0;
