static __attribute__((used)) void collect_string_constants_from_decl(struct C99CodeGenerator * codegen, struct ASTNode * decl) {
    (void)codegen;
    (void)decl;
    if (decl == NULL) {
        return;
    }
    if (decl->type == ASTNodeType_AST_VAR_DECL) {
        if (decl->var_decl_init != NULL) {
            (void)(collect_string_constants_from_expr(codegen, decl->var_decl_init)            );
        }
    } else {
        if (decl->type == ASTNodeType_AST_FN_DECL) {
            struct ASTNode * const saved_current_function_decl = codegen->current_function_decl;
            codegen->current_function_decl = decl;
            struct ASTNode * const body = decl->fn_decl_body;
            if (body != NULL) {
                (void)(collect_string_constants_from_stmt(codegen, body)                );
            }
            codegen->current_function_decl = saved_current_function_decl;
        } else {
            if (decl->type == ASTNodeType_AST_METHOD_BLOCK) {
                int32_t i = 0;
                while (i < decl->method_block_method_count) {
                    struct ASTNode * const m = decl->method_block_methods[i];
                    if (((m != NULL) && (m->type == ASTNodeType_AST_FN_DECL))) {
                        struct ASTNode * const saved_current_function_decl = codegen->current_function_decl;
                        codegen->current_function_decl = m;
                        struct ASTNode * const body = m->fn_decl_body;
                        if (body != NULL) {
                            (void)(collect_string_constants_from_stmt(codegen, body)                            );
                        }
                        codegen->current_function_decl = saved_current_function_decl;
                    }
                    i = (i + 1);
                }
            } else {
            }
        }
    }
}

static __attribute__((used)) void collect_embed_constants_from_decl(struct C99CodeGenerator * codegen, struct ASTNode * decl) {
    (void)codegen;
    (void)decl;
    if (((codegen == NULL) || (decl == NULL))) {
        return;
    }
    if (decl->type == ASTNodeType_AST_VAR_DECL) {
        (void)(collect_embed_constants_from_expr(codegen, decl->var_decl_init)        );
    } else {
        if (decl->type == ASTNodeType_AST_EXTERN_VAR_DECL) {
            (void)(collect_embed_constants_from_expr(codegen, decl->extern_var_decl_init_expr)            );
        } else {
            if (decl->type == ASTNodeType_AST_FN_DECL) {
                (void)(collect_embed_constants_from_stmt(codegen, decl->fn_decl_body)                );
            } else {
                if (decl->type == ASTNodeType_AST_METHOD_BLOCK) {
                    int32_t i = 0;
                    while (i < decl->method_block_method_count) {
                        (void)(collect_embed_constants_from_decl(codegen, decl->method_block_methods[i])                        );
                        i = (i + 1);
                    }
                } else {
                    if (decl->type == ASTNodeType_AST_STRUCT_DECL) {
                        int32_t mi = 0;
                        while (mi < decl->struct_decl_method_count) {
                            (void)(collect_embed_constants_from_decl(codegen, decl->struct_decl_methods[mi])                            );
                            mi = (mi + 1);
                        }
                    } else {
                        if (decl->type == ASTNodeType_AST_TEST_STMT) {
                            (void)(collect_embed_constants_from_stmt(codegen, decl->test_stmt_body)                            );
                        }
                    }
                }
            }
        }
    }
}

static __attribute__((used)) uint32_t read_u32_le(struct uya_slice_uint8_t buf, size_t off) {
    (void)buf;
    (void)off;
    const uint32_t b0 = (uint32_t)buf.ptr[off];
    const uint32_t b1 = (uint32_t)buf.ptr[(off + 1)];
    const uint32_t b2 = (uint32_t)buf.ptr[(off + 2)];
    const uint32_t b3 = (uint32_t)buf.ptr[(off + 3)];
    uint32_t _uya_ret = (((b0 | (b1 << 8)) | (b2 << 16)) | (b3 << 24));
    return _uya_ret;
}

static __attribute__((used)) uint16_t read_u16_le(struct uya_slice_uint8_t buf, size_t off) {
    (void)buf;
    (void)off;
    const uint16_t b0 = (uint16_t)buf.ptr[off];
    const uint16_t b1 = (uint16_t)buf.ptr[(off + 1)];
    uint16_t _uya_ret = (b0 | (b1 << 8));
    return _uya_ret;
}

